reactExercise.solution:
import React, { useReducer } from 'react';

const initialState = { quantity: 1 };

function cartReducer(state, action) {
  switch (action.type) {
    case 'INC':
      return {
        ...state,
        quantity: state.quantity + 1
      };

    case 'DEC':
      return {
        ...state,
        quantity: Math.max(1, state.quantity - 1)
      };

    default:
      return state;
  }
}

export default function App() {
  const [state, dispatch] = useReducer(cartReducer, initialState);

  return (
    <div style={{ padding: '24px', fontFamily: 'sans-serif' }}>
      <h2>Order Quantity Selector</h2>

      <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
        <button id="dec-btn" onClick={() => dispatch({ type: 'DEC' })}>
          -1
        </button>

        <span id="qty-display">{state.quantity}</span>

        <button id="inc-btn" onClick={() => dispatch({ type: 'INC' })}>
          +1
        </button>
      </div>
    </div>
  );
}

