import React from 'react';

const PRODUCTS = [
  { id: 1, name: 'Minimalist Desk Lamp', price: 65 },
  { id: 2, name: 'Ergonomic Chair', price: 320 }
];

export default function App() {
  return (
    <div>
      {PRODUCTS.map(product => (
        <div key={product.id} className="product-name">{product.name}</div>
      ))}
    </div>
  );
}
